// sync-ced-crosswalk.mjs — vendor the ONE CED-2026 crosswalk + label helper
// (CED2026_SINGLE_SOURCE_SPEC.md §1). Explicit local step, like sync-park-calculator.mjs:
// deployed services never read a sibling repo or a parent folder.
//
// Source of truth (edit these, then run this script):
//   2026-crosswalk.json   lib/ced-label.js   lib/ced-label.mjs
//
// Copies (byte-identical; tests/ced-crosswalk-sync.test.js pins them):
//   js/ced2026-labels.js                    ← lib/ced-label.js   (the Desk's <script>)
//   js/ced2026-crosswalk.js                 ← regenerated by build-ced2026-label-data.mjs
//   roster-server/lib/ced-label.js|.mjs     ← lib/ced-label.*    (Railway deploys roster-server/ alone)
//   roster-server/data/2026-crosswalk.json  ← 2026-crosswalk.json
//   <cr>/data/2026-crosswalk.json           ← 2026-crosswalk.json (quiz UI)
//   <cr>/railway-server/data/2026-crosswalk.json (relay frameworks)
//
// Run: node scripts/sync-ced-crosswalk.mjs [path/to/curriculum_render]
import { copyFileSync, existsSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('../', import.meta.url));
const cr = resolve(process.argv[2] || resolve(root, '../curriculum_render'));

const LOCAL_COPIES = [
  ['lib/ced-label.js', 'js/ced2026-labels.js'],
  ['lib/ced-label.js', 'roster-server/lib/ced-label.js'],
  ['lib/ced-label.mjs', 'roster-server/lib/ced-label.mjs'],
  ['2026-crosswalk.json', 'roster-server/data/2026-crosswalk.json'],
];
const CR_COPIES = ['data/2026-crosswalk.json', 'railway-server/data/2026-crosswalk.json'];

for (const [from, to] of LOCAL_COPIES) copyFileSync(resolve(root, from), resolve(root, to));
execFileSync(process.execPath, [resolve(root, 'scripts/build-ced2026-label-data.mjs')], { stdio: 'inherit' });
console.log('CED helper + crosswalk synchronized inside follow-alongs');

if (!existsSync(cr)) {
  console.log('curriculum_render not found at ' + cr + ' — skipped (pass its path as the first argument)');
  process.exit(0);
}
for (const target of CR_COPIES) {
  const dir = resolve(cr, target, '..');
  if (!existsSync(dir)) {
    console.log('  skipped ' + target + ' (no ' + dir + ')');
    continue;
  }
  copyFileSync(resolve(root, '2026-crosswalk.json'), resolve(cr, target));
  console.log('  ' + target);
}
console.log('Crosswalk synchronized to ' + cr);
